<script setup lang="ts">
import { ref } from 'vue'; import { useSubmissionsQuery, useFeedback } from '@/api/queries/domainQueries'; import LcButton from '@/components/ui/LcButton.vue'; import LcCard from '@/components/ui/LcCard.vue'; import LcEmptyState from '@/components/ui/LcEmptyState.vue'; import LcTextarea from '@/components/ui/LcTextarea.vue'
const submissions = useSubmissionsQuery(); const feedback = useFeedback(); const comments = ref<Record<string, string>>({}); const valueFor = (answers: Record<string, unknown> | undefined, key: string) => String((answers ?? {})[key] ?? '—'); const answerRows = (answers?: Record<string, unknown>) => Object.entries(answers ?? {}).map(([key, value]) => ({ key, value: String(value) })); const getComment = (id: string) => comments.value[id] ?? ''; const setComment = (id: string, value: string) => { comments.value[id] = value }
</script>
<template><section class="grid gap-6"><h1 class="font-display text-3xl font-bold">Report submissions</h1><LcEmptyState v-if="(submissions.data.value ?? []).length === 0" title="No submissions"/><LcCard v-for="submission in submissions.data.value ?? []" :key="submission.id"><h2 class="font-display text-xl font-bold">{{ submission.templateName ?? submission.id }}</h2><p class="text-sm text-textMuted">{{ submission.traineeName ?? 'Trainee' }} · submitted: {{ submission.submittedAt ?? 'Date unavailable' }} · frozen version {{ submission.templateVersion ?? '—' }}</p><div class="mt-3 rounded bg-surfaceMuted p-3"><p v-if="submission.frozenFields.length === 0 && answerRows(submission.answers).length === 0" class="text-sm text-textMuted">No answers captured.</p><dl v-else-if="submission.frozenFields.length" class="grid gap-2 text-sm"><div v-for="field in submission.frozenFields" :key="field.key" class="grid gap-1 md:grid-cols-3"><dt class="font-bold">{{ field.label }} <span class="text-textMuted">({{ field.type }})</span></dt><dd class="md:col-span-2">{{ valueFor(submission.answers, field.key) }}</dd></div></dl><dl v-else class="grid gap-2 text-sm"><div v-for="answer in answerRows(submission.answers)" :key="answer.key" class="grid gap-1 md:grid-cols-3"><dt class="font-bold">{{ answer.key }}</dt><dd class="md:col-span-2">{{ answer.value }}</dd></div></dl></div><form class="mt-4 grid gap-3" @submit.prevent="feedback.mutate({ submissionId: submission.id, trainerOverallComment: getComment(submission.id) })"><LcTextarea :model-value="getComment(submission.id)" label="Overall feedback" @update:model-value="setComment(submission.id, $event)"/><LcButton type="submit" :loading="feedback.isPending.value">Save feedback</LcButton></form></LcCard></section></template>
